from flask import Flask, request

app = Flask(__name__)

@app.route("/search")
def search():
    q = request.args.get("q", "")
    return f"<h1>Results for {q}</h1>"

def get_order(cur, order_id):
    cur.execute("SELECT * FROM orders WHERE id = %s" % order_id)
    return cur.fetchone()
